"""Durable staff-operated handoff and investigator-visible scientific state.

This is a trusted-owner API, not an authentication server. Agent tools expose
only the scientific subset. Operator labels record attribution; they never grant
facility authority. No function in this module controls laboratory hardware.
"""

from __future__ import annotations

import hashlib
import mimetypes
from pathlib import Path

from .contracts import (
    ConflictError,
    ContractError,
    canonical,
    check_physical_forecast_source,
    delivered_values,
    digest,
    evidence_ref,
    observation_unit,
    prospective_ref,
    request_record,
    require_id,
)
from .store import Store, now


def _specimen_genealogy(requested: dict, specimen: dict, mapping: dict | None) -> dict:
    """Keep commitment join keys separate from reported physical history."""
    keys = ("specimen_id", "preparation_id", "cycle_id", "lot_id")
    actual = {key: mapping[key] if mapping else None for key in keys}
    return {
        "preparation_id": actual["preparation_id"],
        "cycle_id": actual["cycle_id"],
        "requested_genealogy": {
            **{key: specimen[key] for key in keys if key != "lot_id"},
            "lot_id": requested["lot_id"],
        },
        "actual_genealogy": actual,
        "genealogy_status": "reported" if mapping else "unresolved",
        "genealogy_source": {
            "source_file": mapping["source_file"], "method": mapping["method"]
        } if mapping else None,
    }


def _remaining_mass_after(remaining: float | None, outcome: dict | None) -> float | None:
    if not outcome or not outcome["executed"]:
        return remaining
    if "remaining_mass_g" in outcome:
        return outcome["remaining_mass_g"]
    if outcome.get("consumed_mass_g") is not None and remaining is not None:
        return max(0.0, remaining - outcome["consumed_mass_g"])
    # Unknown destructive consumption must not leave a stale numerical inventory.
    return None if outcome.get("destructive") else remaining


class Campaign:
    @classmethod
    def open(cls, path: str | Path, config: dict | None = None) -> Campaign:
        store = Store(path)
        try:
            with store.transaction():
                existing = store.meta("config")
                if existing is None:
                    existing = {
                        "campaign_id": "ndfeb-sps",
                        "max_file_bytes": 1024**3,
                        **(config or {}),
                    }
                    if (
                        not isinstance(existing["max_file_bytes"], int)
                        or existing["max_file_bytes"] <= 0
                    ):
                        raise ContractError("max_file_bytes must be a positive integer")
                    if existing.get("execution_mode") not in (None, "synthetic", "physical"):
                        raise ContractError("execution_mode must be synthetic or physical")
                    for key in ("max_specimens", "max_requests"):
                        if key in existing and (
                            not isinstance(existing[key], int) or existing[key] <= 0
                        ):
                            raise ContractError(f"{key} must be a positive integer")
                    store.set_meta("config", existing)
                elif config is not None and any(existing.get(k) != v for k, v in config.items()):
                    raise ConflictError("campaign configuration is immutable; use a new campaign")
            return cls(store, existing)
        except BaseException:
            store.close()
            raise

    def __init__(self, store: Store, config: dict):
        self.store, self.config = store, config

    def close(self):
        self.store.close()

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()

    def _action(self, operation, payload, effect, call_id, default_id):
        call_id = require_id(call_id or default_id, "call_id")
        return self.store.action(call_id, {"operation": operation, **payload}, effect)

    def models(self) -> list[dict]:
        return self.store.all("model")

    def model(self, model_id: str) -> dict:
        return self.store.get("model", model_id)

    def adopt_model(
        self,
        source: str,
        rationale: str,
        evidence_ids: list[str],
        *,
        call_id=None,
        expected_evidence_ids: list[str] | None = None,
        artifact_sha256s: list[str] | None = None,
    ) -> dict:
        if not isinstance(source, str) or not source.strip():
            raise ContractError("model source must be nonempty executable text")
        if not isinstance(rationale, str) or not rationale.strip():
            raise ContractError("model rationale is required")
        if not isinstance(evidence_ids, list) or len(evidence_ids) != len(set(evidence_ids)):
            raise ContractError("evidence_ids must be a unique list")
        payload = {"source": source, "rationale": rationale, "evidence_ids": evidence_ids}
        if artifact_sha256s is not None:
            if not isinstance(artifact_sha256s, list) or any(
                not isinstance(item, str) or len(item) != 64
                or any(character not in "0123456789abcdef" for character in item)
                for item in artifact_sha256s
            ) or len(set(artifact_sha256s)) != len(artifact_sha256s):
                raise ContractError("model artifact_sha256s must be a list of distinct SHA256 hashes")
            # Empty bindings keep historical source-only model identities unchanged.
            if artifact_sha256s:
                payload["artifact_sha256s"] = list(artifact_sha256s)
        model_id = "model-" + digest(payload)[:24]
        activation_sequence = self.store.meta("model_activation_sequence") or 0

        def effect():
            if (
                call_id is None
                and (self.store.meta("model_activation_sequence") or 0) != activation_sequence
            ):
                raise ConflictError("model activation changed concurrently; retry adoption")
            visible = {row["evidence_id"] for row in self.evidence()}
            if expected_evidence_ids is not None and set(expected_evidence_ids) != visible:
                raise ConflictError("released evidence changed while the model was being tested")
            if not set(evidence_ids) <= visible:
                raise ContractError("model may cite only released evidence IDs")
            record = {
                "model_id": model_id,
                **payload,
                "source_sha256": hashlib.sha256(source.encode()).hexdigest(),
                "adopted_at": now(),
            }
            if self.store.has("model", model_id):
                record = self.model(model_id)
            else:
                self.store.put("model", model_id, record)
            self.store.set_meta("active_model_id", model_id)
            sequence = (self.store.meta("model_activation_sequence") or 0) + 1
            self.store.set_meta("model_activation_sequence", sequence)
            return {**record, "activated_at": now(), "activation_sequence": sequence}

        return self._action(
            "adopt_model",
            {**payload, "expected_evidence_ids": expected_evidence_ids},
            effect,
            call_id,
            "adopt:" + digest({"model_id": model_id, "activation_sequence": activation_sequence}),
        )

    def submit(
        self,
        request: dict,
        prediction: dict,
        request_id: str,
        *,
        call_id=None,
        expected_model_id: str | None = None,
        expected_evidence_ids: list[str] | None = None,
    ) -> dict:
        request = request_record(request)
        if self.config.get("execution_mode") not in (None, request["origin"]):
            raise ContractError("request origin conflicts with the frozen campaign execution_mode")
        require_id(request_id, "request_id")
        if not isinstance(prediction, dict) or not prediction:
            raise ContractError("an explicit prospective prediction is required")
        canonical(prediction)
        payload = {"request": request, "prediction": prediction, "request_id": request_id}
        operation = request.get("operation", "manufacture")

        def effect():
            if self.store.has("request", request_id):
                previous = self.store.get("request", request_id)
                if previous["request"] != request or previous["prediction"] != prediction:
                    raise ConflictError("request ID already binds different content")
                return previous
            model_id = self.store.meta("active_model_id")
            if model_id is None:
                raise ContractError(
                    "adopt and test an executable model before submitting a prediction"
                )
            evidence = self.evidence()
            check_physical_forecast_source(
                self.model(model_id)["source_sha256"], request, prediction
            )
            evidence_ids = [row["evidence_id"] for row in evidence]
            if expected_model_id is not None and expected_model_id != model_id:
                raise ConflictError("active model changed after the forecast was calculated")
            if expected_evidence_ids is not None and set(expected_evidence_ids) != set(
                evidence_ids
            ):
                raise ConflictError("released evidence changed after the forecast was calculated")
            if operation == "manufacture" and "max_specimens" in self.config and (
                len(self.store.all("specimen")) + len(request["specimens"])
                > self.config["max_specimens"]
            ):
                raise ContractError(
                    "declared specimen request budget exhausted; not a scientific stopping result"
                )
            if (
                "max_requests" in self.config
                and len(self.store.all("request")) >= self.config["max_requests"]
            ):
                raise ContractError(
                    "declared request budget exhausted; not a scientific stopping result"
                )
            input_states = {}
            for specimen in request["specimens"]:
                sid = specimen["specimen_id"]
                if operation == "manufacture":
                    if self.store.has("specimen", sid):
                        raise ConflictError("fresh manufacture requires a fresh specimen ID")
                    continue
                original = self.store.get("specimen", sid)
                if any(original[key] != specimen[key] for key in ("preparation_id", "cycle_id")):
                    raise ConflictError("existing operations must preserve original preparation and SPS cycle")
                if original["lot_id"] != request["lot_id"]:
                    raise ConflictError("existing operations cannot change specimen lot")
                history = self.specimen_history(sid)
                if not history["reported_manufactured"]:
                    raise ContractError("existing operation requires released evidence of manufacture")
                if not history["specimen_available"]:
                    raise ContractError("specimen is unavailable after a reported destructive operation")
                if history["current_stage"] != request["input_stage"]:
                    raise ConflictError("operation input_stage differs from released specimen stage")
                if "prior_processing_conditions" in specimen and canonical(
                    specimen["prior_processing_conditions"]
                ) != canonical(history["processing_history_conditions"]):
                    raise ConflictError("prior_processing_conditions differ from released processing history")
                input_states[sid] = {
                    key: history[key] for key in
                    ("current_stage", "remaining_mass_g", "specimen_available")
                }
            declared_preparations = {
                p["preparation_id"]: p for p in request.get("preparations", [])
            }
            for specimen in request["specimens"]:
                prep_id = specimen["preparation_id"]
                preparation = declared_preparations.get(prep_id)
                if preparation is None:
                    preparation = (self.store.get("preparation", prep_id)
                                   if self.store.has("preparation", prep_id) else
                                   {"preparation_id": prep_id, "lot_id": request["lot_id"]})
                if preparation["lot_id"] != request["lot_id"]:
                    raise ConflictError("shared preparation cannot change its powder lot")
                self.store.put(
                    "preparation",
                    prep_id,
                    preparation,
                )
                if operation != "manufacture":
                    operation_id = "operation-" + digest({"request_id": request_id,
                                                         "specimen_id": specimen["specimen_id"]})[:24]
                    self.store.put("specimen_operation", operation_id, {
                        "operation_id": operation_id, "operation": operation,
                        "request_id": request_id, "specimen_id": specimen["specimen_id"],
                        "manufacturing_request_id": self.store.get("specimen", specimen["specimen_id"])["request_id"],
                        "manufacturing_cycle_id": specimen["cycle_id"],
                        "treatment_cycle_id": specimen.get("treatment_cycle_id"),
                        "input_stage": request["input_stage"], "output_stage": request["output_stage"],
                        "input_state": input_states[specimen["specimen_id"]],
                        "conditions": specimen["conditions"],
                        "measurements": specimen.get("measurements", []),
                    })
                    continue
                self.store.put(
                    "cycle",
                    specimen["cycle_id"],
                    {
                        "cycle_id": specimen["cycle_id"],
                        "lot_id": request["lot_id"],
                        "request_id": request_id,
                        "conditions": specimen["conditions"],
                    },
                )
                self.store.put(
                    "specimen",
                    specimen["specimen_id"],
                    {
                        **specimen,
                        "lot_id": request["lot_id"],
                        "request_id": request_id,
                    },
                )
            for sample in request.get("samples", []):
                self.store.put("sample", sample["sample_id"], sample)
            frozen = {
                **payload,
                "request_sha256": digest(request),
                "model_id": model_id,
                "model_source_sha256": self.model(model_id)["source_sha256"],
                "evidence_ids": evidence_ids,
                "evidence_sha256": digest(evidence),
                "committed_at": now(),
            }
            record = {
                **frozen,
                "prospective_ref": prospective_ref(frozen),
                "status": "HOLD" if request["origin"] == "physical" else "awaiting_operator",
                "execution_authority": "not_granted",
            }
            self.store.put("request", request_id, record)
            return record

        return self._action(
            "submit",
            {
                **payload,
                "expected_model_id": expected_model_id,
                "expected_evidence_ids": expected_evidence_ids,
            },
            effect,
            call_id,
            "submit:" + request_id,
        )

    def request(self, request_id: str) -> dict:
        return self.store.get("request", request_id)

    def submit_operation(self, request: dict, prediction: dict, request_id: str, **kwargs) -> dict:
        """Commit a treatment or measurement on existing bodies through the same path."""
        if request.get("operation") not in {"anneal", "measure"}:
            raise ContractError("submit_operation requires operation=anneal or measure")
        return self.submit(request, prediction, request_id, **kwargs)

    def specimen_history(self, specimen_id: str) -> dict:
        """Released specimen state; planned operations and unpublished returns stay distinct."""
        specimen = self.store.get("specimen", specimen_id)
        releases = self.store.all("release")
        deliveries = [self.store.get("delivery", r["delivery_id"]) for r in releases]
        superseded = {d["corrects_delivery_id"] for d in deliveries if d.get("corrects_delivery_id")}
        active = [d for d in deliveries if d["delivery_id"] not in superseded]
        by_id = {d["delivery_id"]: d for d in deliveries}
        order = {d["delivery_id"]: i for i, d in enumerate(deliveries)}
        def chronology(delivery):
            # A corrected old return replaces that event, rather than pretending
            # its heat treatment happened after subsequently released anneals.
            while delivery.get("corrects_delivery_id"):
                delivery = by_id[delivery["corrects_delivery_id"]]
            return order[delivery["delivery_id"]]
        active.sort(key=chronology)
        history, preparations = [], []
        processing_conditions = []
        stage, remaining_mass, available, manufactured = None, None, True, False
        for delivery in active:
            manufactured_here = specimen_id in delivery.get("manufactured_specimen_ids", [])
            if manufactured_here:
                manufactured = True
            prep = delivery.get("preparation_outcomes", {}).get(specimen["preparation_id"])
            if prep is not None:
                preparations.append({"delivery_id": delivery["delivery_id"], **prep})
            outcome = delivery.get("specimen_outcomes", {}).get(specimen_id)
            observations = [o for o in delivery["observations"] if o.get("specimen_id") == specimen_id]
            if outcome is None and not observations and not manufactured_here:
                continue
            request = self.request(delivery["request_id"])["request"]
            if outcome and outcome["executed"]:
                stage = outcome.get("stage", stage)
                remaining_mass = _remaining_mass_after(remaining_mass, outcome)
                available = outcome.get("specimen_available", available)
                if remaining_mass == 0:
                    # Availability cannot survive complete reported consumption,
                    # including receipts that omit a redundant availability flag.
                    available = False
            operation = request.get("operation", "manufacture")
            actual_conditions = delivery["delivered_conditions"].get(specimen_id)
            if operation in {"manufacture", "anneal"} and (
                manufactured_here or (outcome and outcome["executed"])
            ):
                # These keys describe the receipt identity, not the physical
                # processing law. Keep every other readback, including nulls.
                conditions = {k: v for k, v in (actual_conditions or {}).items() if k not in {
                    "specimen_id", "preparation_id", "cycle_id", "lot_id", "origin", "delivery_status"
                }}
                conditions["operation"] = operation
                if outcome and outcome.get("stage"):
                    conditions["output_stage"] = outcome["stage"]
                processing_conditions.append(conditions)
            history.append({"request_id": delivery["request_id"], "delivery_id": delivery["delivery_id"],
                            "operation": operation, "delivered_conditions": actual_conditions,
                            "origin": delivery["origin"], "outcome": outcome,
                            "observations": observations})
        return {"specimen": specimen,
                "preparation": self.store.get("preparation", specimen["preparation_id"]),
                "reported_preparations": preparations,
                "reported_manufactured": manufactured, "current_stage": stage,
                "remaining_mass_g": remaining_mass, "specimen_available": available,
                "processing_history_conditions": processing_conditions,
                "released_history": history,
                "planned_operations": [o for o in self.store.all("specimen_operation")
                                       if o["specimen_id"] == specimen_id]}

    def processing_history_conditions(self, specimen_id: str) -> list[dict]:
        """Bind reconstruction to actual released readbacks, with unknowns retained."""
        return self.specimen_history(specimen_id)["processing_history_conditions"]

    def accept(
        self,
        request_id: str,
        operator: str,
        notes: str = "",
        *,
        decision="accept",
        deviations: dict | None = None,
        call_id=None,
    ) -> dict:
        require_id(operator, "operator")
        if decision not in {"accept", "deviate", "reject"}:
            raise ContractError("operator decision must be accept, deviate or reject")
        if decision == "deviate" and not deviations:
            raise ContractError(
                "deviation review must describe deviations; it never rewrites the forecast"
            )
        payload = {
            "request_id": request_id,
            "operator": operator,
            "notes": notes,
            "decision": decision,
            "deviations": deviations,
        }

        def effect():
            batch = self.request(request_id)
            record = {
                **payload,
                "request_sha256": batch["request_sha256"],
                "reviewed_at": now(),
                "execution_authority": "not_granted",
                "status": "rejected"
                if decision == "reject"
                else ("HOLD" if batch["request"]["origin"] == "physical" else "accepted"),
            }
            self.store.put("acceptance", request_id, record)
            return record

        return self._action("accept", payload, effect, call_id, "accept:" + request_id)

    def record_execution_failure(
        self, request_id: str, operator: str, code: str, reason: str, *, call_id=None
    ) -> dict:
        """Owner reports an operational failure, never a negative physical observation.

        Supply a fresh call ID for a distinct execution attempt. Replaying the same
        call ID returns its original record. No material consumption is inferred.
        """
        require_id(operator, "operator")
        require_id(code, "failure code")
        if not isinstance(reason, str) or not reason.strip():
            raise ContractError("execution failure requires an actionable reason")
        payload = {"request_id": request_id, "operator": operator, "code": code, "reason": reason}
        action_id = call_id or "execution-failure:" + digest(payload)

        def effect():
            batch = self.request(request_id)
            acceptance = self.store.get("acceptance", request_id)
            if acceptance["decision"] == "reject":
                raise ContractError("a rejected request cannot have an execution attempt")
            failure_id = "failure-" + digest({"call_id": action_id})[:24]
            record = {
                **payload,
                "failure_id": failure_id,
                "request_sha256": batch["request_sha256"],
                "recorded_at": now(),
                "classification": "operational_failure_not_scientific_result",
                "execution_authority": "not_granted",
                "status": "execution_failed",
            }
            self.store.put("execution_failure", failure_id, record)
            return record

        return self._action("execution_failure", payload, effect, action_id, action_id)

    def receive(
        self, request_id: str, delivery: dict, files: dict[str, Path] | None = None, *, call_id=None
    ) -> dict:
        """Owner import only. Receipt is private until separate release; not execution."""
        delivery_id = require_id(delivery.get("delivery_id"), "delivery_id")
        canonical(delivery)
        files = files or {}
        raw_files = {}
        for name, path in files.items():
            require_id(name, "raw logical name")
            if Path(name).name != name or name in {".", ".."}:
                raise ContractError("raw logical names must be basenames")
            blob = self.store.blob(Path(path), self.config["max_file_bytes"])
            raw_files[name] = {
                **blob,
                "name": name,
                "media_type": mimetypes.guess_type(name)[0] or "application/octet-stream",
            }
        payload = {"request_id": request_id, "delivery": delivery, "raw_files": raw_files}

        def effect():
            batch = self.request(request_id)
            requested = batch["request"]
            if delivery.get("origin") != requested["origin"]:
                raise ContractError("delivery origin cannot change the committed execution path")
            acceptance = self.store.get("acceptance", request_id)
            if acceptance["decision"] == "reject":
                raise ContractError("cannot attach a delivery to a rejected request")
            recovered = delivery.get("recovers_failure_id")
            if recovered:
                failure = self.store.get("execution_failure", recovered)
                if failure["request_id"] != request_id:
                    raise ContractError(
                        "recovery must reference an execution failure of this request"
                    )
            if not isinstance(delivery.get("complete"), bool):
                raise ContractError("delivery completeness must be explicit")
            if requested["origin"] == "physical":
                provenance = delivery.get("provenance", {})
                for key in ("facility", "operator", "executed_at"):
                    require_id(provenance.get(key), f"physical provenance {key}")
                if provenance.get("import_mode") != "externally_executed" or not raw_files:
                    raise ContractError(
                        "physical imports require original files and external-execution provenance"
                    )
            observations = delivery.get("observations")
            if not isinstance(observations, list) or not observations:
                raise ContractError("a delivery requires at least one observation")
            specimens = {s["specimen_id"]: s for s in requested["specimens"]}
            samples = {s["sample_id"]: s for s in requested.get("samples", [])}
            actual = delivery.get("delivered_conditions", {})
            if not isinstance(actual, dict) or not set(actual) <= set(specimens):
                raise ContractError("delivered conditions must map only declared specimen IDs")
            manufactured = delivery.get("manufactured_specimen_ids", [])
            if not isinstance(manufactured, list) or not set(manufactured) <= set(specimens):
                raise ContractError("reported manufacture must identify declared specimen IDs")
            if requested.get("operation", "manufacture") != "manufacture" and manufactured:
                raise ContractError("an existing-specimen operation cannot report new manufacture")
            self._validate_operation_outcomes(requested, delivery, raw_files)
            self._validate_corrected_material_history(request_id, delivery)
            normalized = {
                sid: delivered_values(s["conditions"], actual.get(sid))
                for sid, s in specimens.items()
            }
            corrected = delivery.get("corrects_delivery_id")
            if corrected:
                previous = self.store.get("delivery", corrected)
                if previous["request_id"] != request_id:
                    raise ContractError("correction cannot change the underlying batch")
                if any(
                    d.get("corrects_delivery_id") == corrected for d in self.store.all("delivery")
                ):
                    raise ConflictError(
                        "correction chain must extend the latest delivery, not fork"
                    )
            correction_ancestors = set()
            ancestor = corrected
            while ancestor:
                correction_ancestors.add(ancestor)
                ancestor = self.store.get("delivery", ancestor).get("corrects_delivery_id")
            specimen_mapping = self._receive_specimen_mapping(
                request_id, delivery, raw_files, correction_ancestors
            )
            prior_observations = {
                observation["observation_id"]: previous["delivery_id"]
                for previous in self.store.all("delivery")
                for observation in previous["observations"]
            }
            normalized_obs, observation_ids = [], []
            for index, observation in enumerate(observations):
                if not isinstance(observation, dict):
                    raise ContractError("observations must be objects")
                observation = observation_unit(observation)
                kind = observation.get("sample_kind", "specimen")
                identity = {"lot_id": requested["lot_id"]}
                if kind == "specimen":
                    if observation.get("specimen_id") not in specimens:
                        raise ContractError("observation specimen is not in the committed batch")
                    specimen = specimens[observation["specimen_id"]]
                    if requested["origin"] == "physical":
                        identity.update(_specimen_genealogy(
                            requested, specimen, specimen_mapping.get(observation["specimen_id"])
                        ))
                    else:
                        identity.update(
                            {key: specimen[key] for key in ("preparation_id", "cycle_id")}
                        )
                    route = specimen.get("material_route", specimen["conditions"].get("route"))
                    if route is not None:
                        identity["material_route"] = route
                elif kind == "lot":
                    if observation.get("lot_id") != requested["lot_id"]:
                        raise ContractError("observation lot does not match the batch")
                elif kind == "aliquot":
                    if observation.get("sample_id") not in samples:
                        raise ContractError("observation aliquot was not declared")
                    identity["parent_id"] = samples[observation["sample_id"]]["parent_id"]
                else:
                    raise ContractError("unknown observation sampling unit")
                if any(
                    key in observation and observation[key] != value
                    for key, value in identity.items()
                ):
                    raise ContractError(
                        "observation genealogy conflicts with the committed sampling unit"
                    )
                if kind != "specimen" and any(
                    key in observation for key in (
                        "specimen_id", "preparation_id", "cycle_id", "requested_genealogy",
                        "actual_genealogy", "genealogy_source", "genealogy_status",
                    )
                ):
                    raise ContractError(
                        "inventory observations cannot claim manufactured specimen genealogy"
                    )
                for field in ("quantity", "unit"):
                    require_id(observation.get(field), field)
                if "value" not in observation:
                    raise ContractError(
                        "missing measurement value; explicitly use null when unavailable"
                    )
                if observation.get("source_file") and observation["source_file"] not in raw_files:
                    raise ContractError("observation source_file has no supplied original")
                derived_from = observation.get("derived_from", [])
                if derived_from and (
                    not isinstance(derived_from, list)
                    or not all(isinstance(name, str) and name in raw_files for name in derived_from)
                    or not isinstance(observation.get("method"), str)
                    or not observation["method"].strip()
                ):
                    raise ContractError(
                        "derived observations require supplied raw references and a method"
                    )
                if (
                    requested["origin"] == "physical"
                    and observation["value"] is not None
                    and not observation.get("source_file")
                    and not derived_from
                ):
                    raise ContractError(
                        "physical values require a source_file or derived_from raw mapping"
                    )
                oid = require_id(
                    observation.get("observation_id", f"{delivery_id}:{index}"), "observation_id"
                )
                if (
                    oid in prior_observations
                    and prior_observations[oid] not in correction_ancestors
                ):
                    raise ConflictError(
                        "observation ID was already imported; retry the same delivery or declare a correction"
                    )
                observation_ids.append(oid)
                normalized_obs.append(
                    {
                        **observation,
                        **identity,
                        "observation_id": oid,
                        "sample_kind": kind,
                        "evidence_id": f"evidence:{delivery_id}:{index}",
                    }
                )
            if len(set(observation_ids)) != len(observation_ids):
                raise ContractError("observation IDs must be unique within delivery")
            references = {
                name: evidence_ref(
                    f"raw:{delivery_id}:{name}",
                    blob["sha256"],
                    delivery["origin"],
                    blob["media_type"],
                )
                for name, blob in raw_files.items()
            }
            record = {
                **delivery,
                **({"genealogy_version": 1, "specimen_mapping": specimen_mapping}
                   if requested["origin"] == "physical" else {}),
                "request_id": request_id,
                "received_at": now(),
                "observations": normalized_obs,
                "delivered_conditions": normalized,
                "raw_files": raw_files,
                "raw_evidence_refs": references,
                "provenance_assurance": "operator_supplied_not_independently_authenticated"
                if delivery["origin"] == "physical"
                else "conditional_simulation",
                "execution_authority": "not_granted",
            }
            self.store.put("delivery", delivery_id, record)
            return {
                "delivery_id": delivery_id,
                "request_id": request_id,
                "status": "received_unreleased",
                "received_at": record["received_at"],
                "observation_count": len(normalized_obs),
            }

        return self._action("receive", payload, effect, call_id, "receive:" + delivery_id)

    def _validate_operation_outcomes(self, requested: dict, delivery: dict, raw_files: dict):
        """Explicit reports change state; proposals and measurement values alone never do."""
        specimens = {s["specimen_id"]: s for s in requested["specimens"]}
        operation = requested.get("operation", "manufacture")
        outcomes = delivery.get("specimen_outcomes", {})
        preparations = delivery.get("preparation_outcomes", {})
        if not isinstance(outcomes, dict) or not set(outcomes) <= set(specimens):
            raise ContractError("specimen_outcomes must map declared specimen IDs")
        if not isinstance(preparations, dict) or not set(preparations) <= {
            s["preparation_id"] for s in specimens.values()
        }:
            raise ContractError("preparation_outcomes must map declared preparation IDs")
        for outcome in [*outcomes.values(), *preparations.values()]:
            if not isinstance(outcome, dict) or type(outcome.get("executed")) is not bool:
                raise ContractError("operation outcomes require an explicit executed boolean")
            if requested["origin"] == "physical" and outcome.get("source_file") not in raw_files:
                raise ContractError("physical operation outcomes require their own raw source_file")
        for sid, outcome in outcomes.items():
            if "stage" in outcome:
                require_id(outcome["stage"], "reported specimen stage")
            if outcome["executed"] and operation != "manufacture":
                if outcome.get("stage") != requested["output_stage"]:
                    raise ContractError("executed operation must report its committed output stage")
            if not outcome["executed"] and any(key in outcome for key in
                    ("stage", "consumed_mass_g", "remaining_mass_g", "specimen_available")):
                raise ContractError("unexecuted operation cannot change material state")
            for key in ("consumed_mass_g", "remaining_mass_g"):
                value = outcome.get(key)
                if value is not None and (type(value) not in (int, float) or value < 0):
                    raise ContractError(f"{key} must be nonnegative or explicitly unknown")
            for key in ("destructive", "specimen_available"):
                if key in outcome and type(outcome[key]) is not bool:
                    raise ContractError(f"{key} must be boolean")
            if outcome.get("remaining_mass_g") == 0 and outcome.get("specimen_available") is True:
                raise ContractError("zero remaining specimen mass cannot be available")
            if operation != "manufacture" and outcome["executed"]:
                current = self.specimen_history(sid)
                remaining = current["remaining_mass_g"]
                corrected = delivery.get("corrects_delivery_id")
                if corrected:
                    # A correction replaces an earlier event. Compare mass with
                    # the state before that event, not with its old result or a
                    # later sectioning/anneal, and do not bypass conservation.
                    ancestors = set()
                    while corrected:
                        ancestors.add(corrected)
                        corrected = self.store.get("delivery", corrected).get("corrects_delivery_id")
                    remaining = None
                    for event in current["released_history"]:
                        if event["delivery_id"] in ancestors:
                            break
                        remaining = _remaining_mass_after(remaining, event["outcome"])
                else:
                    if current["current_stage"] != requested["input_stage"] or not current["specimen_available"]:
                        raise ConflictError("released specimen state changed before operation completion")
                    prior = specimens[sid].get("prior_processing_conditions")
                    if prior is not None and canonical(prior) != canonical(current["processing_history_conditions"]):
                        raise ConflictError("released processing history changed before operation completion")
                consumed = outcome.get("consumed_mass_g")
                after = outcome.get("remaining_mass_g")
                if remaining is not None and after is not None and after > remaining + 1e-9:
                    raise ContractError("existing-specimen operation cannot increase remaining mass")
                if remaining is not None and consumed is not None:
                    if consumed > remaining + 1e-9:
                        raise ContractError("reported consumption exceeds available specimen mass")
                    if after is not None and abs(after - (remaining - consumed)) > 1e-6:
                        raise ContractError("remaining specimen mass conflicts with reported consumption")
                    if consumed >= remaining and outcome.get("specimen_available") is True:
                        raise ContractError("fully consumed specimen cannot be available")

    def _validate_corrected_material_history(self, request_id: str, delivery: dict):
        """A corrected early state must still support later released operations."""
        corrected = delivery.get("corrects_delivery_id")
        if not corrected:
            return
        ancestors = set()
        affected = set(delivery.get("specimen_outcomes", {}))
        while corrected:
            ancestors.add(corrected)
            previous = self.store.get("delivery", corrected)
            affected.update(previous.get("specimen_outcomes", {}))
            corrected = previous.get("corrects_delivery_id")
        for sid in affected:
            events = self.specimen_history(sid)["released_history"]
            replacement = {"request_id": request_id,
                           "outcome": delivery.get("specimen_outcomes", {}).get(sid)}
            position = next((i for i, event in enumerate(events)
                             if event["delivery_id"] in ancestors), len(events))
            events = [e for e in events if e["delivery_id"] not in ancestors]
            events.insert(position, replacement)
            remaining, stage, available = None, None, True
            for event in events:
                outcome = event["outcome"]
                if not outcome or not outcome["executed"]:
                    continue
                request = self.request(event["request_id"])["request"]
                if request.get("operation", "manufacture") != "manufacture":
                    if not available or stage != request["input_stage"]:
                        raise ConflictError("correction conflicts with later released processing state; review dependent operation records")
                    consumed, after = outcome.get("consumed_mass_g"), outcome.get("remaining_mass_g")
                    if remaining is not None and (
                        (consumed is not None and consumed > remaining + 1e-9)
                        or (after is not None and after > remaining + 1e-9)
                        or (consumed is not None and after is not None
                            and abs(after - (remaining - consumed)) > 1e-6)
                    ):
                        raise ConflictError("correction conflicts with later released mass accounting; review dependent operation records")
                remaining = _remaining_mass_after(remaining, outcome)
                stage = outcome.get("stage", stage)
                available = outcome.get("specimen_available", available) and remaining != 0

    def _receive_specimen_mapping(
        self, request_id: str, delivery: dict, raw_files: dict, correction_ancestors: set
    ) -> dict:
        """Validate owner-reported aliases without changing frozen specimen objects.

        Each delivery must carry its own mapping and original source. Future or
        unreleased mappings are never silently backfilled into older observations.
        """
        mapping = delivery.get("specimen_mapping", {})
        if not isinstance(mapping, dict):
            raise ContractError("specimen_mapping must map requested specimen IDs to actual history")
        if mapping and delivery["origin"] != "physical":
            raise ContractError("specimen_mapping is for externally reported physical history")
        specimens = {
            s["specimen_id"] for s in self.request(request_id)["request"]["specimens"]
        }
        if not set(mapping) <= specimens:
            raise ContractError("specimen_mapping contains an undeclared requested specimen ID")
        keys = ("specimen_id", "preparation_id", "cycle_id", "lot_id")
        for actual in mapping.values():
            if not isinstance(actual, dict) or not set(keys) <= actual.keys():
                raise ContractError(
                    "actual genealogy requires specimen_id, preparation_id, cycle_id and lot_id; "
                    "use null for unknown preparation, cycle or lot"
                )
            require_id(actual["specimen_id"], "actual specimen_id")
            for key in keys[1:]:
                if actual[key] is not None:
                    require_id(actual[key], f"actual {key}")
            source_file = require_id(actual.get("source_file"), "actual genealogy source_file")
            if source_file not in raw_files:
                raise ContractError("actual genealogy source_file requires a supplied original")
            if not isinstance(actual.get("method"), str) or not actual["method"].strip():
                raise ContractError("actual genealogy requires an attributed mapping method")
        previous = self.store.all("delivery")
        superseded = {d["corrects_delivery_id"] for d in previous if d.get("corrects_delivery_id")}
        records = [
            (d["request_id"], sid, actual)
            for d in previous
            if d["delivery_id"] not in superseded | correction_ancestors
            and d["origin"] == "physical" and d.get("genealogy_version") == 1
            for sid, actual in d.get("specimen_mapping", {}).items()
        ]
        records.extend((request_id, sid, actual) for sid, actual in mapping.items())
        bodies, histories, preparations = {}, {}, {}
        for rid, sid, actual in records:
            # A later treatment request refers to the same manufactured body.
            # Keep the original manufacture binding across those requests.
            binding = (self.store.get("specimen", sid)["request_id"], sid)
            body = actual["specimen_id"]
            if body in bodies and bodies[body] != binding:
                raise ConflictError("actual specimen is already mapped to another requested specimen")
            bodies[body] = binding
            known = histories.setdefault(binding, {})
            for key in keys:
                value = actual[key]
                if value is not None:
                    if key in known and known[key] != value:
                        raise ConflictError(
                            "actual genealogy conflicts with a previous mapping; declare a correction"
                        )
                    known[key] = value
            prep, lot = actual["preparation_id"], actual["lot_id"]
            if prep is not None and lot is not None:
                if prep in preparations and preparations[prep] != lot:
                    raise ConflictError("shared actual preparation has conflicting reported lot IDs")
                preparations[prep] = lot
        return mapping

    def release(self, delivery_id: str, reviewer: str, *, call_id=None) -> dict:
        require_id(reviewer, "reviewer")

        def effect():
            delivery = self.store.get("delivery", delivery_id)
            for blob in delivery["raw_files"].values():
                self.store.verify_blob(blob["sha256"])
            corrected = delivery.get("corrects_delivery_id")
            if corrected and not self.store.has("release", corrected):
                raise ContractError(
                    "release the original before its correction to preserve visible chronology"
                )
            self._validate_operation_outcomes(
                self.request(delivery["request_id"])["request"], delivery, delivery["raw_files"]
            )
            self._validate_corrected_material_history(delivery["request_id"], delivery)
            record = {
                "delivery_id": delivery_id,
                "reviewer": reviewer,
                "released_at": now(),
                "delivery_sha256": digest(delivery),
                "review_scope": "owner_data_release_not_facility_admission",
            }
            self.store.put("release", delivery_id, record)
            return record

        return self._action(
            "release",
            {"delivery_id": delivery_id, "reviewer": reviewer},
            effect,
            call_id,
            "release:" + delivery_id,
        )

    def evidence(self) -> list[dict]:
        releases = self.store.all("release")
        deliveries = [(self.store.get("delivery", r["delivery_id"]), r) for r in releases]
        superseded = {
            d["corrects_delivery_id"] for d, _ in deliveries if d.get("corrects_delivery_id")
        }
        evidence = []
        for delivery, release in deliveries:
            if digest(delivery) != release["delivery_sha256"]:
                raise ContractError("released delivery integrity check failed")
            requested = self.request(delivery["request_id"])["request"]
            specimens = {s["specimen_id"]: s for s in requested["specimens"]}
            samples = {s["sample_id"]: s for s in requested.get("samples", [])}
            for observation in delivery["observations"]:
                sid = observation.get("specimen_id")
                identity = {"lot_id": requested["lot_id"]}
                if sid is not None:
                    if delivery["origin"] == "physical" and delivery.get("genealogy_version") == 1:
                        identity.update(_specimen_genealogy(
                            requested, specimens[sid], delivery["specimen_mapping"].get(sid)
                        ))
                    else:
                        # Historical records keep their exact evidence representation.
                        identity.update(
                            {key: specimens[sid][key] for key in ("preparation_id", "cycle_id")}
                        )
                    route = specimens[sid].get(
                        "material_route", specimens[sid]["conditions"].get("route")
                    )
                    identity["material_route"] = route
                    actual_route = delivery["delivered_conditions"].get(sid, {}).get("route")
                    identity["delivered_material_route"] = actual_route
                    identity["material_route_deviation"] = (
                        actual_route is not None and actual_route != route
                    )
                elif observation.get("sample_kind") == "aliquot":
                    identity["parent_id"] = samples[observation["sample_id"]]["parent_id"]
                evidence.append(
                    {
                        **observation,
                        **identity,
                        "delivery_id": delivery["delivery_id"],
                        "request_id": delivery["request_id"],
                        "origin": delivery["origin"],
                        "received_at": delivery["received_at"],
                        "released_at": release["released_at"],
                        "corrects_delivery_id": delivery.get("corrects_delivery_id"),
                        "recovers_failure_id": delivery.get("recovers_failure_id"),
                        "superseded": delivery["delivery_id"] in superseded,
                        "delivered_conditions": delivery["delivered_conditions"].get(sid),
                        "requested_conditions": specimens[sid]["conditions"] if sid else None,
                        "raw_evidence_refs": delivery["raw_evidence_refs"],
                        "provenance_assurance": delivery["provenance_assurance"],
                    }
                )
        return evidence

    def artifacts(self) -> list[dict]:
        return [
            {**blob, "delivery_id": release["delivery_id"]}
            for release in self.store.all("release")
            for blob in self.store.get("delivery", release["delivery_id"])["raw_files"].values()
        ]

    def read_artifact(self, sha256: str, *, max_bytes: int = 1024**2) -> bytes:
        artifacts = [a for a in self.artifacts() if a["sha256"] == sha256]
        if not artifacts:
            raise ContractError("artifact is not attached to released evidence")
        if max_bytes <= 0 or artifacts[0]["size_bytes"] > max_bytes:
            raise ContractError("artifact exceeds bounded read size")
        self.store.verify_blob(sha256)
        return (self.store.blobs / sha256).read_bytes()

    def record_decision(
        self,
        decision: str,
        rationale: str,
        *,
        call_id=None,
        expected_context: dict | None = None,
        expected_model_id: str | None = None,
        expected_evidence_ids: list[str] | None = None,
    ) -> dict:
        require_id(decision, "decision")
        if not isinstance(rationale, str) or not rationale.strip():
            raise ContractError("decision rationale is required")
        payload = {"decision": decision, "rationale": rationale}
        context = {
            "model_id": self.store.meta("active_model_id"),
            "evidence_sha256": digest(self.evidence()),
        }

        def effect():
            current = {
                "model_id": self.store.meta("active_model_id"),
                "evidence_sha256": digest(self.evidence()),
            }
            if (expected_context is not None and current != expected_context) or (
                call_id is None and context != current
            ):
                raise ConflictError(
                    "scientific context changed before recording the decision; retry"
                )
            if expected_model_id is not None and current["model_id"] != expected_model_id:
                raise ConflictError("active model changed before recording the decision")
            if expected_evidence_ids is not None and set(expected_evidence_ids) != {
                row["evidence_id"] for row in self.evidence()
            }:
                raise ConflictError("released evidence changed before recording the decision")
            record = {
                **payload,
                "model_id": self.store.meta("active_model_id"),
                "evidence_ids": [e["evidence_id"] for e in self.evidence()],
                "evidence_sha256": digest(self.evidence()),
                "recorded_at": now(),
            }
            self.store.set_meta("last_decision", record)
            return record

        return self._action(
            "decision",
            {
                **payload,
                "expected_context": expected_context,
                "expected_model_id": expected_model_id,
                "expected_evidence_ids": expected_evidence_ids,
            },
            effect,
            call_id,
            "decision:" + digest({**payload, **context}),
        )

    def state(self) -> dict:
        requests = []
        for batch in self.store.all("request"):
            rid = batch["request_id"]
            released = [
                self.store.get("delivery", r["delivery_id"])
                for r in self.store.all("release")
                if self.store.get("delivery", r["delivery_id"])["request_id"] == rid
            ]
            superseded = {
                d["corrects_delivery_id"] for d in released if d.get("corrects_delivery_id")
            }
            active = [d for d in released if d["delivery_id"] not in superseded]
            review = (
                self.store.get("acceptance", rid) if self.store.has("acceptance", rid) else None
            )
            status = (
                "complete"
                if any(d["complete"] for d in active)
                else ("partial" if active else (review["status"] if review else batch["status"]))
            )
            failures = [f for f in self.store.all("execution_failure") if f["request_id"] == rid]
            latest_failure = failures[-1] if failures else None
            recovered_ids = {d.get("recovers_failure_id") for d in active}
            active_failure = (
                latest_failure
                if latest_failure and latest_failure["failure_id"] not in recovered_ids
                else None
            )
            if active_failure:
                status = "execution_failed"
            requests.append(
                {
                    **batch,
                    "status": status,
                    "operator_review": review,
                    "execution_failures": failures,
                    "active_execution_failure": active_failure,
                    "released_delivery_ids": [d["delivery_id"] for d in released],
                    "execution_status": "HOLD"
                    if batch["request"]["origin"] == "physical"
                    else "simulation_only",
                }
            )
        manufactured = {
            sid
            for release in self.store.all("release")
            for sid in self.store.get("delivery", release["delivery_id"]).get(
                "manufactured_specimen_ids", []
            )
        }
        return {
            "campaign_id": self.config["campaign_id"],
            "active_model_id": self.store.meta("active_model_id"),
            "requests": requests,
            "evidence": self.evidence(),
            "last_decision": self.store.meta("last_decision"),
            "specimen_histories": [self.specimen_history(s["specimen_id"])
                                   for s in self.store.all("specimen")],
            "resources": {
                "specimens_requested": len(self.store.all("specimen")),
                "specimens_reported_manufactured": len(manufactured),
                "max_specimens": self.config.get("max_specimens"),
                "existing_specimen_operations_requested": len(self.store.all("specimen_operation")),
                "actual_material_consumption": "not_inferred_from_requests",
            },
            "physical_execution": "HOLD: no independent facility authority is installed",
        }

    def history(self) -> list[dict]:
        """Agent history excludes private receipt/release actions and their timing."""
        return [
            event for event in self.store.history() if event["kind"] not in {"receive", "release"}
        ]

    def verify(self) -> dict:
        """Owner integrity audit; does not release data or certify physical truth."""
        check = self.store.db.execute("PRAGMA integrity_check").fetchone()[0]
        if check != "ok":
            raise ContractError("SQLite integrity check failed")
        count = 0
        for row in self.store.db.execute("SELECT kind,id FROM objects").fetchall():
            self.store.get(row["kind"], row["id"])
            count += 1
        for model in self.models():
            if hashlib.sha256(model["source"].encode()).hexdigest() != model["source_sha256"]:
                raise ContractError("model source digest binding failed")
        for batch in self.store.all("request"):
            frozen = {
                key: value
                for key, value in batch.items()
                if key not in {"prospective_ref", "status", "execution_authority"}
            }
            if digest(frozen) != batch["prospective_ref"]["sha256"]:
                raise ContractError("prospective prediction digest binding failed")
            if digest(batch["request"]) != batch["request_sha256"]:
                raise ContractError("requested batch digest binding failed")
            if self.model(batch["model_id"])["source_sha256"] != batch["model_source_sha256"]:
                raise ContractError("prospective model source binding failed")
        blobs = {v["sha256"] for d in self.store.all("delivery") for v in d["raw_files"].values()}
        for sha256 in blobs:
            self.store.verify_blob(sha256)
        self.evidence()
        return {
            "status": "verified",
            "scope": "storage_integrity_only",
            "objects_checked": count,
            "raw_artifacts_checked": len(blobs),
            "physical_execution_authority": "not_granted",
        }
